// Audit reproductions. Only synthetic records in a disposable local schema.
require('reflect-metadata');
const { spawn, spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { parseEnv } = require('node:util');
const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcrypt');
const { DateTime } = require('luxon');
const { StaffService } = require('../dist/staff/staff.service');
const { UsersService } = require('../dist/users/users.service');
const { FinanceService } = require('../dist/payments/finance.service');
const { PaymentsService } = require('../dist/payments/payments.service');
const root = path.join(__dirname, '..');
const output = path.join(root, '../docs/audits/2026-10-19');
const settings = parseEnv(fs.readFileSync(path.join(root, '.env'), 'utf8').replace(/^\uFEFF/, ''));
const source = new URL(process.env.DATABASE_URL || settings.DATABASE_URL);
assert.ok(['localhost', '127.0.0.1'].includes(source.hostname));
if (process.env.AUDIT_DB_PORT) source.port = process.env.AUDIT_DB_PORT;
const schema = `audit_20261019_${Date.now()}`;
assert.match(schema, /^audit_20261019_\d+$/);
const target = new URL(source); target.searchParams.set('schema', schema);
const env = { ...process.env, ...settings, DATABASE_URL: target.href, JWT_SECRET: 'isolated-audit-test-only-secret-32-bytes-long', NODE_ENV: 'test', PORT: '3000', PUBLIC_LEADS_ENABLED: 'false' };
for (const key of Object.keys(env)) if (key.startsWith('VK_')) delete env[key];
const adminDb = new PrismaClient({ datasources: { db: { url: source.href } } });
const p = new PrismaClient({ datasources: { db: { url: target.href } } });
let server, created = false, stopping = false;
async function cleanup() {
  if (stopping) return;
  stopping = true;
  if (server && server.exitCode === null) { server.kill(); await new Promise(resolve => server.once('exit', resolve)); }
  await p.$disconnect();
  if (created) await adminDb.$executeRawUnsafe(`DROP SCHEMA "${schema}" CASCADE`);
  await adminDb.$disconnect();
}
(async () => {
  await adminDb.$executeRawUnsafe(`CREATE SCHEMA "${schema}"`); created = true;
  const migration = spawnSync(process.execPath, ['node_modules/prisma/build/index.js', 'migrate', 'deploy'], { cwd: root, env, encoding: 'utf8', windowsHide: true });
  assert.equal(migration.status, 0, 'Disposable schema migration failed');
  const passwordHash = await bcrypt.hash('audit-test-password', 10);
  const admin = await p.user.create({ data: { email: 'audit-admin@test.local', passwordHash, role: 'ADMIN' } });
  const actor = { id: admin.id, role: 'ADMIN' };
  const trainer = await p.trainer.create({ data: { name: 'Аудит тренер' } });
  const userA = await p.user.create({ data: { email: 'audit-trainer-a@test.local', passwordHash, role: 'TRAINER', trainerId: trainer.id } });
  const userB = await p.user.create({ data: { email: 'audit-trainer-b@test.local', passwordHash, role: 'TRAINER' } });
  const staff = new StaffService(p), users = new UsersService(p), finance = new FinanceService(p), payments = new PaymentsService(p);
  const a = await staff.saveProfile({ userId: userA.id, fullName: 'Тренер А', roleTitle: 'Тренер', lessonRate: 1000 }, actor);
  const b = await staff.saveProfile({ userId: userB.id, fullName: 'Тренер Б', roleTitle: 'Тренер', lessonRate: 1000 }, actor);
  const client = await p.client.create({ data: { name: 'Синтетический клиент', phone: '+79990001122' } });
  const service = await p.service.create({ data: { name: 'Синтетическое занятие', durationMinutes: 60, price: 1000 } });
  const arena = await p.arena.create({ data: { name: 'Аудит манеж' } });
  const horse = await p.horse.create({ data: { name: 'Аудит лошадь' } });
  const month = DateTime.now().setZone('Europe/Moscow').startOf('month');
  const from = month.toISODate(), to = month.endOf('month').toISODate();
  const first = month.plus({ days: 1, hours: 10 }).toJSDate(), end = month.plus({ days: 1, hours: 11 }).toJSDate();
  await p.booking.create({ data: { trainerId: trainer.id, clientId: client.id, horseId: horse.id, arenaId: arena.id, serviceType: 'dressage', status: 'completed', costAmount: 1000, startTime: first, endTime: end } });
  const direct = (await staff.calculate({ staffId: a.id, from, to }, actor)).data[0];
  assert.equal(direct.lessonsCount, 0);
  const results = [{ finding: 'PAY-01', description: 'Completed standalone Booking is ignored by payroll', completedBookings: 1, payrollLessons: direct.lessonsCount, payrollAmount: direct.totalAmount.toString() }];
  await p.lesson.create({ data: { trainerId: trainer.id, serviceId: service.id, startTime: first, endTime: end, status: 'COMPLETED', bookings: { create: { trainerId: trainer.id, clientId: client.id, costAmount: 1000, legacyLessonBinding: true, status: 'completed', startTime: first, endTime: end } } } });
  const rowA = await staff.savePayroll({ staffId: a.id, from, to, bonuses: 0, penalties: 0 }, actor);
  await staff.payout({ calculationId: rowA.id, expectedTotal: 1000, paymentMethod: 'CASH' }, actor);
  const summary = await finance.summary({ from, to, page: 1, pageSize: 20 });
  assert.equal(summary.balanceCash.toString(), '-1000');
  results.push({ finding: 'CASH-02', description: 'Payout succeeds without receipts or starting cash', balanceCash: summary.balanceCash.toString() });
  await users.setTrainer(userA.id, null); await users.setTrainer(userB.id, trainer.id);
  const rowB = await staff.savePayroll({ staffId: b.id, from, to, bonuses: 0, penalties: 0 }, actor);
  await staff.payout({ calculationId: rowB.id, expectedTotal: 1000, paymentMethod: 'CASH' }, actor);
  assert.equal(await p.expense.count({ where: { category: 'SALARY' } }), 2);
  results.push({ finding: 'PAY-02', description: 'Rebinding trainer to another staff account allows paying the same Lesson twice', completedLessons: 1, salaryExpenses: 2, totalPaid: '2000' });
  const manual = await payments.create({ clientId: client.id, amount: 500, method: 'CASH', status: 'PAID' });
  assert.equal(manual.cashierId, null);
  await payments.remove(manual.id);
  assert.equal(await p.payment.count({ where: { id: manual.id } }), 0);
  results.push({ finding: 'CASH-01', description: 'Legacy API creates PAID receipts without author and hard-deletes them', paidRecordDeleted: true });
  const sick = await staff.savePayroll({ staffId: a.id, from: month.minus({ months: 1 }).toISODate(), to: month.minus({ months: 1 }).endOf('month').toISODate(), bonuses: 1000, penalties: 999 }, actor);
  assert.equal(sick.totalAmount.toString(), '1');
  results.push({ finding: 'LAW-01', description: '99.9% salary deduction is accepted without reason/document', gross: 1000, deduction: 999, net: sick.totalAmount.toString() });
  fs.writeFileSync(path.join(output, 'reproductions.json'), JSON.stringify({ date: '2026-10-19', syntheticOnly: true, results }, null, 2));
  console.log(JSON.stringify(results, null, 2));
  if (process.env.AUDIT_SERVE !== '1') { await cleanup(); return; }
  server = spawn(process.execPath, ['dist/main.js'], { cwd: root, env, stdio: 'ignore', windowsHide: true });
  server.once('exit', () => { if (!stopping) void cleanup(); });
  console.log('AUDIT_SERVER: synthetic schema on localhost:3000; send stop to clean up.');
  process.stdin.resume(); process.stdin.on('data', data => { if (data.toString().includes('stop')) void cleanup().then(() => process.exit(0)); });
  process.once('SIGINT', () => void cleanup().then(() => process.exit(0)));
  process.once('SIGTERM', () => void cleanup().then(() => process.exit(0)));
})().catch(async error => { console.error(error.name, error.code || '', 'Audit reproduction failed'); await cleanup(); process.exitCode = 1; });
